ALTER PROCEDURE [dbo].[AdditionalCostExport]	@StartDate DateTime,	@EndDate DateTime,	@VerticalId bigint,	@IsActiveStatus intAS BEGIN	if(@IsActiveStatus = 2)  --Active records	SELECT  	v.Name AS Vertical ,	o.Name AS OilTypeName,		ot.RatePerMt,	CONVERT(VARCHAR,ot.ValidFrom,103) AS ValidFrom,	CONVERT(VARCHAR,ot.ValidTo,103) AS ValidTo,	ot.IsActive	FROM AdditionalCosts ot	JOIN Verticals v ON ot.VerticalId = v.Id	JOIN OilTypes o ON o.id = ot.OilTypeId		WHERE CAST(@Startdate as date) <= CAST(ot.CreatedDate as date) and CAST(ot.CreatedDate as date) <= CAST(@Enddate as date) and (ot.VerticalId = @VerticalId or @VerticalId = 0) and ot.IsActive = 1	ORDER By ot.CreatedDate DESC	else if(@IsActiveStatus = 3) --InActive records	SELECT  	v.Name AS Vertical ,	o.Name AS OilTypeName,		ot.RatePerMt,	CONVERT(VARCHAR,ot.ValidFrom,103) AS ValidFrom,	CONVERT(VARCHAR,ot.ValidTo,103) AS ValidTo,	ot.IsActive	FROM AdditionalCosts ot	JOIN Verticals v ON ot.VerticalId = v.Id	JOIN OilTypes o ON o.id = ot.OilTypeId		WHERE CAST(@Startdate as date) <= CAST(ot.CreatedDate as date) and CAST(ot.CreatedDate as date) <= CAST(@Enddate as date) and (ot.VerticalId = @VerticalId or @VerticalId = 0) and ot.IsActive = 0	ORDER By ot.CreatedDate DESC	else 	SELECT  	v.Name AS Vertical ,	o.Name AS OilTypeName,		ot.RatePerMt,	CONVERT(VARCHAR,ot.ValidFrom,103) AS ValidFrom,	CONVERT(VARCHAR,ot.ValidTo,103) AS ValidTo,	ot.IsActive	FROM AdditionalCosts ot	JOIN Verticals v ON ot.VerticalId = v.Id	JOIN OilTypes o ON o.id = ot.OilTypeId		WHERE CAST(@Startdate as date) <= CAST(ot.CreatedDate as date) and CAST(ot.CreatedDate as date) <= CAST(@Enddate as date) and (ot.VerticalId = @VerticalId or @VerticalId = 0) 	ORDER By ot.CreatedDate DESCEND;